-- Execute uma vez em bancos já existentes, após a versão anterior do schema.
CREATE TABLE IF NOT EXISTS world_creatures(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,map_code VARCHAR(40) NOT NULL,code VARCHAR(40) NOT NULL,name VARCHAR(60) NOT NULL,tile_x SMALLINT UNSIGNED NOT NULL,tile_y SMALLINT UNSIGNED NOT NULL,level TINYINT UNSIGNED NOT NULL DEFAULT 1,health SMALLINT UNSIGNED NOT NULL,max_health SMALLINT UNSIGNED NOT NULL,experience_reward SMALLINT UNSIGNED NOT NULL DEFAULT 10,UNIQUE KEY uq_creature_map_code(map_code,code),KEY idx_creature_map_position(map_code,tile_x,tile_y),CONSTRAINT fk_creature_map FOREIGN KEY(map_code) REFERENCES maps(code) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO world_creatures(map_code,code,name,tile_x,tile_y,level,health,max_health,experience_reward) VALUES
('elarion','slime_green','Limo Verde',6,7,1,45,45,18),('elarion','wolf_young','Lobo Jovem',10,8,2,65,65,28),('elarion','thorn_beetle','Besouro Espinhoso',8,5,1,55,55,22)
ON DUPLICATE KEY UPDATE name=VALUES(name),tile_x=VALUES(tile_x),tile_y=VALUES(tile_y),level=VALUES(level),max_health=VALUES(max_health),experience_reward=VALUES(experience_reward);
